fn clip(arr: &Vec<i8>, min_val: i8, max_val: i8) -> Vec<i8> {
    // Requires: The length of the input array must be non-negative.
    // Ensures: The output vector has the same length as the input array.
    //          Each element in the output vector is within the range [min_val, max_val].
    //          If min_val > max_val, all elements in the output vector are equal to max_val.
    // Decreases: The length of the input array.
    // Invariant: For all elements x in arr, the output will contain elements that are
    //            clipped to the range [min_val, max_val].
    assert!(arr.len() >= 0);
    
    if min_val > max_val {
        // If the lower bound is greater than the upper bound,
        // return a vector filled with the upper bound value.
        let result = vec![max_val; arr.len()];
        assert!(result.len() == arr.len());
        assert!(result.iter().all(|&x| x == max_val));
        result
    } else {
        // Otherwise, clip each element in the array.
        let result: Vec<i8> = arr.iter()
            .map(|&x| {
                if x < min_val {
                    assert!(x < min_val);
                    min_val
                } else if x > max_val {
                    assert!(x > max_val);
                    max_val
                } else {
                    assert!(min_val <= x && x <= max_val);
                    x
                }
            })
            .collect();
        
        assert!(result.len() == arr.len());
        assert!(result.iter().all(|&x| min_val <= x && x <= max_val));
        result
    }
}